  outline: 3px solid var(--border-focus);
  outline-offset: 2px;
}

/* invalid state */
.form-field.is-invalid .checkbox {
  border-color: var(--danger);
}

.checkbox__label {
  font-size: 0.95rem;
  color: var(--text);
  cursor: pointer;
  user-select: none;
}

.required-marker {
  color: var(--danger);
  margin-left: 0.2em;
