  border-radius: var(--radius);
  padding: 2rem 2.25rem 2.25rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45);
}

.card__header {
  margin-bottom: 1.75rem;
}

.card__title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
}

.card__subtitle {
  color: var(--text-muted);
  font-size: 0.9rem;
  margin-top: 0.35rem;
}

